import React from 'react';
import styles from './Button.module.css';

const Button = ({
                    children,
                    variant = 'primary',
                    size = 'medium',
                    fullWidth = false,
                    icon: Icon,
                    onClick,
                    type = 'button',
                    className = ''
                }) => {
    const buttonClasses = [
        styles.button,
        styles[variant],
        styles[size],
        fullWidth && styles.fullWidth,
        className
    ].filter(Boolean).join(' ');

    return (
        <button
            type={type}
            className={buttonClasses}
            onClick={onClick}
        >
            {Icon && <Icon className={styles.icon} />}
            <span className={styles.content}>{children}</span>
        </button>
    );
};

export default Button;
